#!/usr/bin/env python3
"""Compare every generated byte in two result directories; fail on any difference."""
import argparse, hashlib, json
from pathlib import Path

def hashes(path):
    return {p.relative_to(path).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()
            for p in sorted(path.rglob('*')) if p.is_file()}

def main():
    ap=argparse.ArgumentParser();ap.add_argument('first',type=Path);ap.add_argument('second',type=Path)
    ap.add_argument('--out',type=Path);a=ap.parse_args()
    h1,h2=hashes(a.first),hashes(a.second)
    difference=[p for p in sorted(set(h1)|set(h2)) if h1.get(p)!=h2.get(p)]
    result=dict(status='FAIL' if difference else 'PASS',files=len(h1),differences=difference,first_hashes=h1,second_hashes=h2)
    if a.out:a.out.parent.mkdir(parents=True,exist_ok=True);a.out.write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(dict(status=result['status'],files=result['files'],differences=difference)))
    if difference:raise SystemExit(1)

if __name__=='__main__':main()
